index 0000000..d7a932f
--- /dev/null
+++ b/internal/ext/importer.go
@@ -0,0 +1,178 @@
+package ext
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"strings"
+
+	flipt "github.com/markphelps/flipt/rpc/flipt"
+	"gopkg.in/yaml.v2"
+)
+
+type creator interface {
+	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
+	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
+	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
+	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
+	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
+	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
+}
+
+type Importer struct{ store creator }
+
+func NewImporter(store creator) *Importer { return &Importer{store: store} }
+func (i *Importer) Import(ctx context.Context, r io.Reader) error {
+	var (
+		dec = yaml.NewDecoder(r)
+		doc = new(Document)
+	)
+
+	if err := dec.Decode(doc); err != nil {
+		return fmt.Errorf("importing: %w", err)
+	}
+
+	var (
+		// map flagKey => *flag
+		createdFlags = make(map[string]*flipt.Flag)
+		// map segmentKey => *segment
+		createdSegments = make(map[string]*flipt.Segment)
+		// map flagKey:variantKey => *variant
+		createdVariants = make(map[string]*flipt.Variant)
+	)
+
+	// create flags/variants
+	for _, f := range doc.Flags {
+		flag, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{
+			Key:         f.Key,
+			Name:        f.Name,
+			Description: f.Description,
+			Enabled:     f.Enabled,
+		})
+
+		if err != nil {
+			return fmt.Errorf("importing flag: %w", err)
+		}
+
+		for _, v := range f.Variants {
+			var attachment string
+			if v.Attachment != nil {
+				if raw, ok := v.Attachment.(string); ok && (strings.HasPrefix(strings.TrimSpace(raw), "{") || strings.HasPrefix(strings.TrimSpace(raw), "[")) && json.Valid([]byte(raw)) {
+					attachment = raw
+				} else {
+					data, err := json.Marshal(convert(v.Attachment))
+					if err != nil {
+						return fmt.Errorf("encoding attachment for variant %q: %w", v.Key, err)
+					}
+					attachment = string(data)
+				}
+			}
+			variant, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{
+				FlagKey:     f.Key,
+				Key:         v.Key,
+				Name:        v.Name,
+				Description: v.Description,
+				Attachment:  attachment,
+			})
+
+			if err != nil {
+				return fmt.Errorf("importing variant: %w", err)
+			}
+
+			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
+		}
+
+		createdFlags[flag.Key] = flag
+	}
+
+	// create segments/constraints
+	for _, s := range doc.Segments {
+		segment, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
+			Key:         s.Key,
+			Name:        s.Name,
+			Description: s.Description,
+		})
+
+		if err != nil {
+			return fmt.Errorf("importing segment: %w", err)
+		}
+
+		for _, c := range s.Constraints {
+			_, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
+				SegmentKey: s.Key,
+				Type:       flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
+				Property:   c.Property,
+				Operator:   c.Operator,
+				Value:      c.Value,
+			})
+
+			if err != nil {
+				return fmt.Errorf("importing constraint: %w", err)
+			}
+		}
+
+		createdSegments[segment.Key] = segment
+	}
+
+	// create rules/distributions
+	for _, f := range doc.Flags {
+		// loop through rules
+		for _, r := range f.Rules {
+			rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{
+				FlagKey:    f.Key,
+				SegmentKey: r.SegmentKey,
+				Rank:       int32(r.Rank),
+			})
+
+			if err != nil {
+				return fmt.Errorf("importing rule: %w", err)
+			}
+
+			for _, d := range r.Distributions {
+				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
+				if !found {
+					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
+				}
+
+				_, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
+					FlagKey:   f.Key,
+					RuleId:    rule.Id,
+					VariantId: variant.Id,
+					Rollout:   d.Rollout,
+				})
+
+				if err != nil {
+					return fmt.Errorf("importing distribution: %w", err)
+				}
+			}
+		}
+	}
+
+	return nil
+}
+
+func convert(v interface{}) interface{} {
+	switch x := v.(type) {
+	case map[interface{}]interface{}:
+		m := make(map[string]interface{}, len(x))
+		for k, val := range x {
+			m[fmt.Sprint(k)] = convert(val)
+		}
+		return m
+	case map[string]interface{}:
+		m := make(map[string]interface{}, len(x))
+		for k, val := range x {
+			m[k] = convert(val)
+		}
+		return m
+	case []interface{}:
+		a := make([]interface{}, len(x))
+		for j, val := range x {
+			a[j] = convert(val)
+		}
+		return a
+	default:
+		return v
+	}
+}
