+package ext
+
+import (
+	"encoding/json"
+	"reflect"
+	"testing"
+
+	"gopkg.in/yaml.v2"
+)
+
+func TestNestedAttachmentConversion(t *testing.T) {
+	var doc Document
+	if err := yaml.Unmarshal([]byte("flags:\n  - key: test\n    enabled: true\n    variants:\n      - key: a\n        attachment:\n          nested:\n            - count: 2\n              empty: null\n            - true\n          3: value\n"), &doc); err != nil {
+		t.Fatal(err)
+	}
+	got, err := json.Marshal(convert(doc.Flags[0].Variants[0].Attachment))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var decoded interface{}
+	if err := json.Unmarshal(got, &decoded); err != nil {
+		t.Fatal(err)
+	}
+	want := map[string]interface{}{"3": "value", "nested": []interface{}{map[string]interface{}{"count": float64(2), "empty": nil}, true}}
+	if !reflect.DeepEqual(decoded, want) {
+		t.Fatalf("attachment = %#v, want %#v", decoded, want)
+	}
+}
